// ShaderToy GLSL Fragment Shader
#define N 4  // Number of points

vec3 points[N] = vec3[](
    vec3(0., 0., 1.0),  // Point 1: (x=0.2, y=0.3, value=1.0)
    vec3(0.49, 0.49, 1.0),
    vec3(0.5, 0.5, 0.0),
    vec3(1., 1., 0.)
);

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize fragment coordinates to [0,1] range
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Initialize weights and value accumulator
    float weightSum = 0.0;
    float valueSum = 0.0;

    // Loop through each point
    for (int i = 0; i < N; i++) {
        vec2 pointPos = points[i].xy;  // Point position (x, y)
        float value = points[i].z;    // Point value (z)

        // Calculate distance between the pixel and the point
        float dist = distance(uv, pointPos);

        // Calculate weight using a smooth inverse distance formula
        float weight = 1.0 / (dist * dist + 0.01); // Add epsilon to avoid division by zero

        // Accumulate weighted value and weight
        valueSum += value * weight;
        weightSum += weight;
    }

    // Compute the final smoothed value
    float smoothValue = valueSum / weightSum;

    // Output as a grayscale color
    fragColor = vec4(vec3(smoothValue), 1.0);
}
